package com.borislav.freeflow.combat;

import com.borislav.freeflow.network.AnimationPayload;
import net.fabricmc.fabric.api.networking.v1.PlayerLookup;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.server.level.ServerPlayer;

import java.util.List;
import java.util.Set;

/**
 * Combat animations (assets/freeflow/player_animations/freeflow_combat.json, generated by
 * tools/gen_animations.py from tools/clips_player.py), how strikes pick one, and how hard each
 * one hits.
 */
public final class Anim {
	private Anim() {}

	// Close strikes
	public static final String JAB_RIGHT = "jab_right";
	public static final String JAB_LEFT = "jab_left";
	public static final String HOOK_RIGHT = "hook_right";
	public static final String HOOK_LEFT = "hook_left";
	public static final String ELBOW = "elbow";
	public static final String KNEE = "knee";
	public static final String FRONT_KICK = "front_kick";
	public static final String SIDE_KICK = "side_kick";
	public static final String SPIN_BACKFIST = "spin_backfist";
	public static final String HAYMAKER = "haymaker";
	// Lunging strikes
	public static final String FLYING_KICK = "flying_kick";
	public static final String FLYING_PUNCH = "flying_punch";
	// Beatdown / finisher
	public static final String BEATDOWN_RIGHT = "beatdown_right";
	public static final String BEATDOWN_LEFT = "beatdown_left";
	public static final String FINISHER = "finisher";
	// Other moves
	public static final String COUNTER = "counter";
	public static final String COUNTER_KICK = "counter_kick";
	public static final String COUNTER_THROW = "counter_throw";
	public static final String STUN = "stun";
	public static final String EVADE = "evade";
	public static final String ROLL = "roll";
	public static final String SLIDE = "slide";
	/** Client-only looping stance clips: guard, side/back steps, advancing in guard, sprinting. */
	public static final String STANCE = "stance";
	public static final String SHUFFLE = "shuffle";
	public static final String ADVANCE = "advance";
	public static final String RUN = "run";
	public static final String VAULT = "vault";
	public static final String GROUND_TAKEDOWN = "ground_takedown";
	public static final String SPECIAL_TAKEDOWN = "special_takedown";

	// Gadget moves, ready for the gadget system (nothing triggers them yet). Play each with
	// play(player, name, lead) where lead is how many ticks until the moment in brackets; the
	// matching enemy reaction (MobReaction) is sent on that tick.
	/** Quick thrown blade in the middle of a fight [the blade leaves the hand] -> GADGET_STRUCK. */
	public static final String THROW_QUICK = "throw_quick";
	/** Aimed throw: looping aim pose. It plays until another move replaces it or stop(player). */
	public static final String THROW_AIM = "throw_aim";
	/** Aimed throw let go from the aim pose [the blade leaves the hand] -> GADGET_STRUCK. */
	public static final String THROW_RELEASE = "throw_release";
	/** Grapple claw fired at an enemy [the shot] -> HOOKED when it bites. Drops the aim after 14 ticks. */
	public static final String CLAW_FIRE = "claw_fire";
	/** Looping: line held taut on a hooked enemy, or while a long shot is still in flight. Ended like THROW_AIM. */
	public static final String CLAW_HOLD = "claw_hold";
	/** The hooked enemy is yanked in [the yank] -> PULLED. */
	public static final String CLAW_PULL = "claw_pull";
	/** Clothesline on the enemy arriving on the line [the arm connects] -> CLOTHESLINED. */
	public static final String CLAW_SLAM = "claw_slam";

	public static final List<String> ALL = List.of(JAB_RIGHT, JAB_LEFT, HOOK_RIGHT, HOOK_LEFT, ELBOW, KNEE, FRONT_KICK,
			SIDE_KICK, SPIN_BACKFIST, HAYMAKER, FLYING_KICK, FLYING_PUNCH, BEATDOWN_RIGHT, BEATDOWN_LEFT, FINISHER,
			COUNTER, COUNTER_KICK, COUNTER_THROW, STUN, EVADE, ROLL, VAULT, SLIDE, STANCE, SHUFFLE, ADVANCE, RUN, GROUND_TAKEDOWN,
			SPECIAL_TAKEDOWN, THROW_QUICK, THROW_AIM, THROW_RELEASE, CLAW_FIRE, CLAW_HOLD,
			CLAW_PULL, CLAW_SLAM);

	/** Combo strings: the flow gets flashier as the combo grows. */
	private static final List<String> TIER_LOW = List.of(JAB_RIGHT, JAB_LEFT, HOOK_RIGHT, FRONT_KICK);
	private static final List<String> TIER_MID = List.of(HOOK_LEFT, HOOK_RIGHT, ELBOW, KNEE, SIDE_KICK);
	private static final List<String> TIER_HIGH = List.of(HOOK_RIGHT, SPIN_BACKFIST, KNEE, HAYMAKER, ELBOW, SIDE_KICK);

	/** Lunges at least this many ticks long become flying attacks. */
	public static final int FLYING_TRAVEL_TICKS = 3;

	public static final int LIGHT = 1;
	public static final int MEDIUM = 2;
	public static final int HEAVY = 3;

	private static final Set<String> HEAVY_MOVES = Set.of(SIDE_KICK, SPIN_BACKFIST, HAYMAKER, FLYING_KICK, FLYING_PUNCH,
			FINISHER, SPECIAL_TAKEDOWN, GROUND_TAKEDOWN, COUNTER_KICK, COUNTER_THROW);
	private static final Set<String> LIGHT_MOVES = Set.of(JAB_RIGHT, JAB_LEFT, BEATDOWN_RIGHT, BEATDOWN_LEFT);

	/** Picks the strike animation from the lunge length and the combo tier. */
	public static String chooseStrike(int index, int travelTicks, int combo) {
		if (travelTicks >= FLYING_TRAVEL_TICKS) {
			return index % 2 == 0 ? FLYING_KICK : FLYING_PUNCH;
		}
		List<String> tier = combo >= 10 ? TIER_HIGH : combo >= 5 ? TIER_MID : TIER_LOW;
		return tier.get(Math.floorMod(index, tier.size()));
	}

	public static String beatdown(int index) {
		return index % 2 == 0 ? BEATDOWN_RIGHT : BEATDOWN_LEFT;
	}

	/** Hit strength of a move: LIGHT, MEDIUM or HEAVY (drives damage, knockback and impact effects). */
	public static int strength(String move) {
		if (HEAVY_MOVES.contains(move)) {
			return HEAVY;
		}
		return LIGHT_MOVES.contains(move) ? LIGHT : MEDIUM;
	}

	/** Ends whatever move is playing on {@code player} (the looping aim/hold poses), back to the stance. */
	public static void stop(ServerPlayer player) {
		play(player, AnimationPayload.STOP, AnimationPayload.FROM_START);
	}

	/** Plays the animation from its start on {@code player}, for the player and everyone tracking them. */
	public static void play(ServerPlayer player, String name) {
		play(player, name, AnimationPayload.FROM_START);
	}

	/**
	 * Plays a blow whose hit lands {@code lead} ticks from now: clients line the clip's impact
	 * frame up with that tick.
	 */
	public static void play(ServerPlayer player, String name, int lead) {
		AnimationPayload payload = new AnimationPayload(player.getId(), name, lead);
		if (ServerPlayNetworking.canSend(player, AnimationPayload.TYPE)) {
			ServerPlayNetworking.send(player, payload);
		}
		for (ServerPlayer other : PlayerLookup.tracking(player)) {
			if (other != player && ServerPlayNetworking.canSend(other, AnimationPayload.TYPE)) {
				ServerPlayNetworking.send(other, payload);
			}
		}
	}
}
